// Seed wiki + demo:wiki smoke test: the agent-generated seed loads with zero problems, every note is generated by the agent,
// no human: actor exists anywhere in an actor field, the generator is deterministic, and the scripted MCP demo session runs.
import test from 'node:test';
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { mkdtempSync, cpSync, readFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { loadVault, walk } from '../../src/wiki/vault.js';
const ROOT = fileURLToPath(new URL('../../', import.meta.url));
const env = Object.fromEntries(Object.entries(process.env).filter(([k]) => k !== 'NODE_TEST_CONTEXT'));

test('seed wiki: both dialects load cleanly with agent provenance and no human actors', () => {
  for (const [v, dialect] of [['maritime-kb', 'vault-ld'], ['app-docs', 'okf']]) {
    const m = loadVault(join(ROOT, 'demo/wiki', v));
    assert.equal(m.dialect, dialect); assert.deepEqual(m.problems, []);
    for (const n of m.notes) {
      if (!n.fm) continue; // README / prose
      assert.deepEqual(n.problems, [], n.path);
      assert.equal(n.trust.generated?.by, 'grokbot/reverse-engineering-analyst', n.path);
      for (const x of n.trust.verified) assert.ok(!x.by.startsWith('human:'), `${n.path} has a human verifier`);
      assert.notEqual(n.trust.tier, 'human-reviewed');
    }
  }
});

test('seed generator is deterministic (re-running it reproduces the committed files byte-for-byte)', () => {
  const d = mkdtempSync(join(tmpdir(), 'sg-seed-'));
  const r = spawnSync(process.execPath, [join(ROOT, 'demo/wiki/build-seed.mjs'), '--out', d], { encoding: 'utf8', env }); assert.equal(r.status, 0, r.stderr);
  for (const v of ['maritime-kb', 'app-docs']) { assert.deepEqual(walk(join(d, v)), walk(join(ROOT, 'demo/wiki', v))); for (const f of walk(join(ROOT, 'demo/wiki', v))) assert.equal(readFileSync(join(d, v, f), 'utf8'), readFileSync(join(ROOT, 'demo/wiki', v, f), 'utf8'), `${v}/${f}`); }
});

test('demo:wiki scripted agent session runs end to end', () => {
  const r = spawnSync(process.execPath, [join(ROOT, 'explore/demos/wiki/run.mjs'), '--json'], { encoding: 'utf8', env: { ...env, STREAMGRAPH_PROCESSING: 'off' }, timeout: 120000 });
  assert.equal(r.status, 0, r.stdout + r.stderr);
  const s = JSON.parse(/SUMMARY (.*)/.exec(r.stdout)[1]);
  assert.equal(s.vaults.length, 2); assert.ok(s.search.includes('Ports/Norfolk.md'));
  assert.equal(s.verify, 'machine-confirmed'); assert.equal(s.humanRefused, true);
  assert.ok(s.historyAdded >= 1); assert.ok(s.turtleBytes > 1000);
  assert.equal(s.tiers['human-reviewed'] ?? 0, 0, 'nothing is human-reviewed until Billy verifies it');
});
